package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class CustomerResolutionsAcceptance {
 static String route(String id){return "/api/openservice/customer-cases/"+id+"/resolution";}
 static Map<String,Object> get(WorkflowSupport h,String id,String user)throws Exception{return CustomerCasesAcceptance.get(h,route(id),user);}
 static Map<String,Object> body(WorkflowSupport h,String id,String operation,String user)throws Exception{var p=get(h,id,user);var body=map("operation",operation,"revision",object(p.get("resolution")).get("revision"),"record_revision",Integer.parseInt(object(p.get("record")).get("sys_mod_count").toString()));if(operation.equals("propose"))body.putAll(map("code","workaround","solution","Reviewed solution <script>safe</script>"));else body.put("reason","Reviewed public decision");return body;}
 static Map<String,Object> command(WorkflowSupport h,String id,String operation,String user)throws Exception{var r=h.json("POST",route(id),body(h,id,operation,user),auth(user));assertEquals(200,r.statusCode(),html(r));return object(parsed(r).get("result"));}
 static String[] setup(WorkflowSupport h)throws Exception{var ids=CustomerRepliesAcceptance.setup(h);assertEquals(200,h.json("PATCH","/api/now/table/customer_case/"+ids[0],map("state","working"),auth("CustomerAgent")).statusCode());return ids;}
 static void run(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];assertEquals(0,object(get(h,id,"CustomerOne").get("resolution")).get("revision"));var p=command(h,id,"propose","CustomerAgent");assertEquals("resolved",object(p.get("record")).get("state"));assertEquals(true,get(h,id,"CustomerOne").get("can_decide"));var stale=body(h,id,"accept","CustomerOne");for(String state:List.of("closed","working"))assertEquals(409,h.json("PATCH","/api/now/table/customer_case/"+id,map("state",state),auth("admin")).statusCode());assertEquals(403,h.json("POST",route(id),body(h,id,"accept","CustomerAgent"),auth("CustomerAgent")).statusCode());p=command(h,id,"reject","CustomerOne");assertEquals("working",object(p.get("record")).get("state"));assertEquals("rejected",object(p.get("resolution")).get("status"));assertEquals(409,h.json("POST",route(id),stale,auth("CustomerOne")).statusCode());command(h,id,"propose","CustomerAgent");command(h,id,"withdraw","CustomerAgent");assertEquals("withdrawn",object(get(h,id,"CustomerOne").get("resolution")).get("status"));command(h,id,"propose","CustomerAgent");p=command(h,id,"accept","CustomerOne");assertEquals("closed",object(p.get("record")).get("state"));assertEquals("accepted",object(p.get("resolution")).get("status"));assertEquals(3,objects(p.get("history")).size());assertEquals(409,h.json("PATCH","/api/now/table/customer_case/"+id,map("description","Changed after acceptance"),auth("admin")).statusCode());assertEquals(409,h.json("PATCH","/api/now/table/customer_case/"+id,map("state","working"),auth("admin")).statusCode());assertEquals(403,h.json("POST",route(id),body(h,id,"reopen","CustomerAgent"),auth("CustomerAgent")).statusCode());command(h,id,"reopen","admin");p=get(h,id,"CustomerOne");assertEquals("working",object(p.get("record")).get("state"));assertEquals(1,object(p.get("resolution")).get("reopened"));var imported=h.json("POST","/api/openservice/import/customer_case?dry_run=false",List.of(map("sys_id",id,"state","closed")),auth("admin"));assertEquals(200,imported.statusCode());assertEquals(1,parsed(imported).get("skipped"));assertEquals("working",object(get(h,id,"CustomerOne").get("record")).get("state"));try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.record(db,"customer_case",id);object(item.get("data")).put("state","closed");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,item)).status);}command(h,id,"propose","CustomerAgent");command(h,id,"accept","CustomerOne");new Store(h.environment);assertEquals(4,objects(get(h,id,"CustomerOne").get("history")).size());assertEquals(200,h.get("/record/customer_case/"+id+"/resolution",auth("CustomerOne")).statusCode());assertEquals(204,h.json("DELETE","/api/now/table/customer_case/"+id,map(),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_customer_resolution WHERE record_id=?",id));}
 }
 static void authority(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var propose=body(h,id,"propose","CustomerAgent");for(String user:List.of("CustomerTwo","CustomerOther","CustomerOutsider"))assertEquals(404,h.get(route(id),auth(user)).statusCode());assertEquals(403,h.json("POST",route(id),propose,auth("CustomerOne")).statusCode());var original=CustomerRepliesAcceptance.ServiceSchema(h);for(String field:List.of("description","state")){var schema=new LinkedHashMap<>(original);schema.put("field_rules",map(field,map("read_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"customer_case",schema);try{assertEquals(403,h.get(route(id),auth("CustomerAgent")).statusCode());assertEquals(403,h.json("POST",route(id),propose,auth("CustomerOne")).statusCode());}finally{ReferencePickerAcceptance.writeSchema(h,"customer_case",original);}}
  var schema=new LinkedHashMap<>(original);schema.put("field_rules",map("description",map("write_roles",List.of("admin"))));ReferencePickerAcceptance.writeSchema(h,"customer_case",schema);try{assertEquals(403,h.json("POST",route(id),propose,auth("CustomerAgent")).statusCode());assertEquals(false,get(h,id,"CustomerAgent").get("can_propose"));}finally{ReferencePickerAcceptance.writeSchema(h,"customer_case",original);}schema=new LinkedHashMap<>(original);schema.put("record_roles",map("update",List.of("admin")));ReferencePickerAcceptance.writeSchema(h,"customer_case",schema);try{assertEquals(403,h.json("POST",route(id),propose,auth("CustomerAgent")).statusCode());assertEquals(false,get(h,id,"CustomerAgent").get("can_propose"));}finally{ReferencePickerAcceptance.writeSchema(h,"customer_case",original);}
  command(h,id,"propose","CustomerAgent");var decision=body(h,id,"accept","CustomerOne");CustomerCasesAcceptance.contact(h,ids[2],"CustomerOne",true);assertEquals(404,h.json("POST",route(id),decision,auth("CustomerOne")).statusCode());CustomerCasesAcceptance.contact(h,ids[1],"CustomerOne",true);RecordScopesAcceptance.member(h,ids[3],ids[4],false);assertEquals(404,h.get(route(id),auth("CustomerAgent")).statusCode());RecordScopesAcceptance.member(h,ids[3],ids[4],true);
  schema=new LinkedHashMap<>(original);schema.put("version",99);ReferencePickerAcceptance.writeSchema(h,"customer_case",schema);try{assertEquals(false,get(h,id,"CustomerOne").get("current"));assertEquals(false,get(h,id,"CustomerOne").get("can_decide"));assertEquals(409,h.json("POST",route(id),decision,auth("CustomerOne")).statusCode());command(h,id,"withdraw","CustomerAgent");command(h,id,"propose","CustomerAgent");command(h,id,"accept","CustomerOne");}finally{ReferencePickerAcceptance.writeSchema(h,"customer_case",original);}command(h,id,"reopen","admin");
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];for(String path:List.of(route(id),"/record/customer_case/"+id+"/resolution")){assertEquals(path.startsWith("/api/")?405:403,h.json("DELETE",path,map(),auth("admin")).statusCode());assertEquals(400,h.get(path+"?x=1",auth("CustomerAgent")).statusCode());}assertEquals(404,h.get(route(Values.id()),auth("admin")).statusCode());var good=body(h,id,"propose","CustomerAgent");for(var bad:List.of(map(),map("operation","invalid"),map("operation","propose"))){assertEquals(400,h.json("POST",route(id),bad,auth("CustomerAgent")).statusCode());}for(String key:List.of("code","solution","revision","record_revision")){var b=new LinkedHashMap<>(good);b.put(key,key.endsWith("revision")?-1:" ");assertEquals(400,h.json("POST",route(id),b,auth("CustomerAgent")).statusCode());}Map<String,Object> bad=new LinkedHashMap<>(good);bad.put("code","wrong");assertEquals(400,h.json("POST",route(id),bad,auth("CustomerAgent")).statusCode());bad=new LinkedHashMap<>(good);bad.put("solution","x".repeat(4001));assertEquals(400,h.json("POST",route(id),bad,auth("CustomerAgent")).statusCode());bad=new LinkedHashMap<>(good);bad.put("revision",5);assertEquals(409,h.json("POST",route(id),bad,auth("CustomerAgent")).statusCode());bad=new LinkedHashMap<>(good);bad.put("record_revision",0);assertEquals(409,h.json("POST",route(id),bad,auth("CustomerAgent")).statusCode());assertEquals(400,h.protectedForm("/record/customer_case/"+id+"/resolution",map("revision","bad","record_revision","1"),auth("CustomerAgent")).statusCode());
  String entitlement=CustomerCasesAcceptance.entitlement(h,ids[1],0),legacy=CustomerCasesAcceptance.create(h,entitlement,CustomerCasesAcceptance.body(h,entitlement,"CustomerOne"),"CustomerOne").get("sys_id").toString();for(String state:List.of("working","resolved"))assertEquals(200,h.json("PATCH","/api/now/table/customer_case/"+legacy,map("state",state),auth("CustomerAgent")).statusCode());assertEquals(400,h.json("POST",route(legacy),body(h,legacy,"accept","CustomerOne"),auth("CustomerOne")).statusCode());assertEquals(200,h.json("PATCH","/api/now/table/customer_case/"+legacy,map("state","closed"),auth("CustomerAgent")).statusCode());assertEquals(400,h.json("POST",route(legacy),body(h,legacy,"reopen","admin"),auth("admin")).statusCode());
  for(String op:List.of("withdraw","accept","reject","reopen")){String user=op.equals("reopen")?"admin":op.equals("withdraw")?"CustomerAgent":"CustomerOne";assertEquals(400,h.json("POST",route(id),body(h,id,op,user),auth(user)).statusCode());}good.put("solution","x".repeat(4000));assertEquals(200,h.json("POST",route(id),good,auth("CustomerAgent")).statusCode());assertEquals(400,h.json("POST",route(id),body(h,id,"propose","CustomerAgent"),auth("CustomerAgent")).statusCode());bad=body(h,id,"reject","CustomerOne");bad.put("reason"," ");assertEquals(400,h.json("POST",route(id),bad,auth("CustomerOne")).statusCode());bad.put("reason","x".repeat(4001));assertEquals(400,h.json("POST",route(id),bad,auth("CustomerOne")).statusCode());assertEquals(403,h.json("POST",route(id),body(h,id,"withdraw","CustomerOne"),auth("CustomerOne")).statusCode());
 }
 static void gates(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];var original=CustomerRepliesAcceptance.ServiceSchema(h);
  for(String blocked:List.of("flow","write","transition")){var schema=object(JSON.readValue(JSON.writeValueAsString(original),Map.class));schema.put("version",1);if(blocked.equals("flow"))object(schema.get("flow")).put("resolved",List.of("working"));else if(blocked.equals("write"))schema.put("field_rules",map("state",map("type","string","write_roles",List.of("admin","agent"))));else schema.put("transition_rules",map("closed",map("roles",List.of("admin","agent"))));ReferencePickerAcceptance.writeSchema(h,"customer_case",schema);try{command(h,id,"propose","CustomerAgent");var request=body(h,id,"accept","CustomerOne");assertEquals(blocked.equals("flow")?409:403,h.json("POST",route(id),request,auth("CustomerOne")).statusCode());assertEquals("pending",object(get(h,id,"CustomerOne").get("resolution")).get("status"));assertEquals(request.get("revision"),object(get(h,id,"CustomerOne").get("resolution")).get("revision"));command(h,id,"withdraw","CustomerAgent");}finally{ReferencePickerAcceptance.writeSchema(h,"customer_case",original);}}
  var schema=new LinkedHashMap<>(original);schema.put("version",1);schema.put("transition_rules",map("closed",map("min_approvals",1)));ReferencePickerAcceptance.writeSchema(h,"customer_case",schema);String task;
  try{try(var db=h.store.open()){PlatformFoundationTest.bind(db);var record=Service.record(db,"customer_case",id);WorkTasks.command(db,"customer_case",id,map("operation","configure","revision",0,"record_revision",record.get("revision"),"close_at","closed"));var page=WorkTasks.page(db,"customer_case",id);var created=WorkTasks.command(db,"customer_case",id,map("operation","create","revision",object(page.get("plan")).get("revision"),"record_revision",Integer.parseInt(object(page.get("parent")).get("sys_mod_count").toString()),"summary","Verify fix before closure","details","Check the customer result","group_id",ids[3],"required",true,"predecessors",List.of()));task=objects(created.get("tasks")).getFirst().get("task_id").toString();db.connection.commit();}
   command(h,id,"propose","CustomerAgent");var request=body(h,id,"accept","CustomerOne");assertEquals(409,h.json("POST",route(id),request,auth("CustomerOne")).statusCode());try(var db=h.store.open()){var admin=ApprovalTest.as(db,"admin");String approval=Approvals.request(db,"customer_case",id,admin,map("expected_revision",Service.record(db,"customer_case",id).get("revision"),"approver","CustomerAgent","target_state","closed","reason","Review customer closure")).get("approval_id").toString();Approvals.decide(db,"customer_case",id,approval,ApprovalTest.as(db,"CustomerAgent"),map("decision","approved","comment","Approved solution"));db.connection.commit();}assertEquals(409,h.json("POST",route(id),request,auth("CustomerOne")).statusCode());assertEquals("pending",object(get(h,id,"CustomerOne").get("resolution")).get("status"));
   for(String operation:List.of("claim","complete"))try(var db=h.store.open()){ApprovalTest.as(db,"CustomerAgent");var page=WorkTasks.page(db,"customer_case",id);var action=map("operation",operation,"revision",objects(page.get("tasks")).getFirst().get("revision"),"record_revision",Integer.parseInt(object(page.get("parent")).get("sys_mod_count").toString()),"task_id",task);if(operation.equals("complete"))action.put("outcome","Customer fix verified");WorkTasks.command(db,"customer_case",id,action);db.connection.commit();}command(h,id,"accept","CustomerOne");assertEquals("closed",object(get(h,id,"CustomerOne").get("record")).get("state"));
  }finally{ReferencePickerAcceptance.writeSchema(h,"customer_case",original);}
 }
 static void limits(WorkflowSupport h)throws Exception{
  var ids=setup(h);String id=ids[0];command(h,id,"propose","CustomerAgent");try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.record(db,"customer_case",id);object(item.get("data")).put("state","open");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,item)).status);}assertEquals(409,h.json("PATCH","/api/now/table/customer_case/"+id,map("description","Changed pending context"),auth("CustomerAgent")).statusCode());var old=body(h,id,"accept","CustomerOne");CustomerRepliesAcceptance.publish(h,id,CustomerRepliesAcceptance.body(h,id,false));assertEquals(409,h.json("POST",route(id),old,auth("CustomerOne")).statusCode());command(h,id,"accept","CustomerOne");CustomerRepliesAcceptance.publish(h,id,CustomerRepliesAcceptance.body(h,id,false));assertEquals("accepted",object(get(h,id,"CustomerOne").get("resolution")).get("status"));try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.record(db,"customer_case",id);object(item.get("data")).put("state","working");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,item)).status);db.customerResolutionReopen=true;assertFalse(CustomerResolutions.reopening(db,map("table","incident"),"working"));assertFalse(CustomerResolutions.reopening(db,item,"open"));db.customerResolutionReopen=false;}
  command(h,id,"reopen","admin");try(var db=h.store.open()){for(int n=2;n<=50;n++)db.update("INSERT INTO os_customer_resolution(resolution_id,record_id,ordinal,revision,status,code,solution,proposer_name,reason,created,decided,snapshot) VALUES(?,?,?,2,'withdrawn','workaround','Retained solution','Support','Revised',?,?,'')",Values.id(),id,n,now(),now());db.connection.commit();}assertEquals(50,objects(get(h,id,"CustomerOne").get("history")).size());assertEquals(400,h.json("POST",route(id),body(h,id,"propose","CustomerAgent"),auth("CustomerAgent")).statusCode());
 }

}
